# bench-control-ct-final: private CPU kernel (internet on). Frozen Cascaded Tanks run for config ct_phys8.
# AUTO-GENERATED by kernels/ct_final/make_kernel.py from kernel_main.py + the payload (do not edit script.py).
#
# Stages (each logged; every stage before `final` is train-only and never reads the test record's values):
#   1 payload   extract the byte-identical frozen sources, verify every sha256 against the embedded manifest
#   2 venv      Python 3.12 venv in /tmp with the SAME package versions as the local dry run (uv)
#   3 git       throw-away repo so ct/final.py's clean-tree guard passes; git tree hashes must equal the control repo's
#   4 data      Google Drive loader URL; zip and .mat sha256 must match; no fallback
#   5 gate      ct/final.py --allow-dirty --seeds 0 (TRAIN only) must reproduce the local dry-run train RMSE
#   6 final     ct/final.py results/FREEZE_ct_phys8.json --seeds 0..9 (ONE scored test run per seed, logged in TEST-LOG.md); never repeated
#   7 compare / plots / aggregate / edge: each in its own try/except; final is never re-run if one of them fails
import base64, glob, hashlib, io, json, os, platform, re, shutil, subprocess, sys, tarfile, time, traceback

T0 = time.time()
OUT = "/kaggle/working/out"
ROOT = "/tmp/ctrepo"
VENV = "/tmp/ctvenv"
PY = VENV + "/bin/python"
NAME = "ct_phys8"
FREEZE = "results/FREEZE_ct_phys8.json"
SEEDS = [str(s) for s in range(10)]
GATE_TRAIN_RMSE, GATE_TOL = 0.1785, 0.003   # local dry run (STATUS.md): full-record fit, train RMSE 0.1785
PINS = ["numpy==2.5.3", "scipy==1.18.1", "jax==0.11.2", "jaxlib==0.11.2", "nonlinear-benchmarks==1.0.1",
        "matplotlib<3.11", "progressbar==2.5", "rarfile==4.5", "tqdm==4.70.1", "requests==2.34.2"]
EXPECT_VERSIONS = {"numpy": "2.5.3", "scipy": "1.18.1", "jax": "0.11.2", "jaxlib": "0.11.2", "nonlinear_benchmarks": "1.0.1"}

PAYLOAD_B64 = "__PAYLOAD_B64__"
EXPECT = json.loads(r'''__EXPECT_JSON__''')

ENV = dict(os.environ, OMP_NUM_THREADS="1", MKL_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1",
           XLA_FLAGS="--xla_cpu_multi_thread_eigen=false intra_op_parallelism_threads=1",
           PYTHONDONTWRITEBYTECODE="1", PYTHONUNBUFFERED="1")

os.makedirs(OUT + "/stages", exist_ok=True)
STATUS = {}


class Abort(Exception):
    pass


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, flush=True)


def status(stage, **kw):
    STATUS[stage] = dict(t=round(time.time() - T0, 1), **kw)
    json.dump(STATUS, open(OUT + "/stage_status.json", "w"), indent=1)


def snapshot():
    """Copy the small outputs to /kaggle/working/out (called during and after the run so a crash loses nothing)."""
    try:
        if os.path.exists(ROOT + "/TEST-LOG.md"):
            shutil.copy2(ROOT + "/TEST-LOG.md", OUT + "/TEST-LOG.md")
        for pat, sub in ((ROOT + "/results/ct_*", "results"), (ROOT + "/results/figs/*", "results/figs"),
                         (ROOT + "/runs/ct_final_*", "runs"), (ROOT + "/edge_out/*.c", "edge"), (ROOT + "/edge_out/params/*", "edge/params")):
            os.makedirs(f"{OUT}/{sub}", exist_ok=True)
            for f in glob.glob(pat):
                if os.path.isfile(f):
                    shutil.copy2(f, f"{OUT}/{sub}/")
    except Exception:
        log("snapshot failed:", traceback.format_exc())


def sh(cmd, name, env=None, cwd=None, check=True, on_line=None):
    """Run a command, stream its output into the kernel log and OUT/stages/<name>.log. Returns (returncode, text)."""
    log("$", " ".join(cmd))
    buf = []
    with open(f"{OUT}/stages/{name}.log", "a") as lf:
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env or ENV, cwd=cwd, bufsize=1)
        for line in p.stdout:
            print(line, end="", flush=True)
            lf.write(line)
            buf.append(line)
            if on_line:
                on_line(line)
        rc = p.wait()
    if check and rc != 0:
        raise Abort(f"{name}: command failed with exit code {rc}")
    return rc, "".join(buf)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def stage_banner():
    info = dict(utc_start=time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(T0)), python=sys.version, platform=platform.platform(),
                cpu_count=os.cpu_count(), kernel="sankalpsthakur/bench-control-ct-final")
    try:
        info["cpu_model"] = [l.split(":", 1)[1].strip() for l in open("/proc/cpuinfo") if l.lower().startswith("model name")][0]
        info["mem_total_kb"] = [int(l.split()[1]) for l in open("/proc/meminfo") if l.startswith("MemTotal")][0]
    except Exception:
        pass
    json.dump(info, open(OUT + "/env.json", "w"), indent=1)
    log("ENV", json.dumps(info))
    log("EXPECT", json.dumps({k: v for k, v in EXPECT.items() if k != "manifest"}))


def stage_payload():
    if os.path.exists(ROOT):
        shutil.rmtree(ROOT)
    os.makedirs(ROOT)
    raw = base64.b64decode(PAYLOAD_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
        try:
            tf.extractall(ROOT, filter="data")
        except TypeError:
            tf.extractall(ROOT)
    bad = []
    for rel, want in EXPECT["manifest"].items():
        p = os.path.join(ROOT, rel)
        got = sha256_file(p) if os.path.exists(p) else "MISSING"
        if got != want:
            bad.append((rel, want, got))
    for p in glob.glob(ROOT + "/ct/*"):
        if os.path.basename(p) not in {os.path.basename(k) for k in EXPECT["manifest"] if k.startswith("ct/")}:
            bad.append((p, "not in manifest", "extra file"))
    for rel in EXPECT.get("executable", []):
        os.chmod(os.path.join(ROOT, rel), 0o755)
    os.makedirs(ROOT + "/runs", exist_ok=True)
    os.makedirs(ROOT + "/results", exist_ok=True)
    manifest_report = {rel: dict(sha256=sha256_file(os.path.join(ROOT, rel))) for rel in sorted(EXPECT["manifest"])}
    json.dump(manifest_report, open(OUT + "/manifest_verified.json", "w"), indent=1)
    for rel in sorted(EXPECT["manifest"]):
        log("SHA256", manifest_report[rel]["sha256"], rel)
    if bad:
        raise Abort("payload sha256 mismatch: " + json.dumps(bad))
    status("payload", ok=True, files=len(EXPECT["manifest"]))


def stage_venv():
    sh([sys.executable, "-m", "pip", "install", "-q", "uv"], "venv")
    uvbin = subprocess.check_output([sys.executable, "-c", "import uv; print(uv.find_uv_bin())"], text=True).strip()
    sh([uvbin, "venv", "--python", "3.12", VENV], "venv")
    sh([uvbin, "pip", "install", "--python", PY, *PINS], "venv")
    rc, txt = sh([uvbin, "pip", "freeze", "--python", PY], "venv")
    open(OUT + "/venv_freeze.txt", "w").write(txt)
    code = ("import sys, json, numpy, scipy, jax, jaxlib, matplotlib, nonlinear_benchmarks, importlib.metadata as m;"
            "print('VERSIONS', json.dumps(dict(python=sys.version.split()[0], numpy=numpy.__version__, scipy=scipy.__version__, jax=jax.__version__,"
            "jaxlib=jaxlib.__version__, matplotlib=matplotlib.__version__, nonlinear_benchmarks=m.version('nonlinear_benchmarks'))))")
    rc, txt = sh([PY, "-c", code], "venv")
    got = json.loads(txt.split("VERSIONS", 1)[1].strip().splitlines()[0])
    open(OUT + "/versions.json", "w").write(json.dumps(got, indent=1))
    wrong = {k: (v, got.get(k)) for k, v in EXPECT_VERSIONS.items() if got.get(k) != v}
    if wrong:
        raise Abort("package versions differ from the local dry run: " + json.dumps(wrong))
    status("venv", ok=True, versions=got)


def stage_git():
    g = ["git", "-c", "user.name=ct-kernel", "-c", "user.email=ct-kernel@localhost"]
    sh(["git", "init", "-q", "."], "git", cwd=ROOT)
    sh(g + ["add", ".gitignore", "ct", FREEZE], "git", cwd=ROOT)
    sh(g + ["commit", "-q", "-m", "frozen sources, byte-identical to control repo " + EXPECT["repo_head"][:7]], "git", cwd=ROOT)
    _, t_ct = sh(["git", "rev-parse", "HEAD:ct"], "git", cwd=ROOT)
    _, t_fr = sh(["git", "rev-parse", "HEAD:" + FREEZE], "git", cwd=ROOT)
    _, head = sh(["git", "rev-parse", "HEAD"], "git", cwd=ROOT)
    t_ct, t_fr, head = t_ct.strip(), t_fr.strip(), head.strip()
    log("GIT tree ct", t_ct, "expected", EXPECT["git_tree_ct"])
    log("GIT blob freeze", t_fr, "expected", EXPECT["git_blob_freeze"])
    ok = t_ct == EXPECT["git_tree_ct"] and t_fr == EXPECT["git_blob_freeze"]
    status("git", ok=ok, kernel_head=head, tree_ct=t_ct, blob_freeze=t_fr)
    if not ok:
        raise Abort("git hashes of the frozen sources differ from the control repo")
    _, st = sh(["git", "status", "--porcelain", "--", "ct", "results/FREEZE_*.json"], "git", cwd=ROOT)
    if st.strip():
        raise Abort("tree not clean after commit: " + st)


def stage_data():
    last = None
    for attempt in range(1, 4):
        shutil.rmtree(ROOT + "/data", ignore_errors=True)
        rc, txt = sh([PY, "tools/ct_data_check.py", EXPECT["data_zip_sha256"], EXPECT["data_mat_sha256"]], "data", cwd=ROOT, check=False)
        last = txt
        if rc == 0:
            line = [l for l in txt.splitlines() if l.startswith("DATA_CHECK ")][-1]
            status("data", ok=True, attempt=attempt, info=json.loads(line[len("DATA_CHECK "):]))
            return
        log(f"data attempt {attempt} failed (rc={rc}); retrying in 20 s")
        time.sleep(20)
    raise Abort("data check failed after 3 attempts (Drive blocked or checksum mismatch); NOT falling back to any other copy. Last output tail: " + (last or "")[-800:])


def stage_gate():
    rc, txt = sh([PY, "ct/final.py", FREEZE, "--seeds", "0", "--allow-dirty"], "gate", cwd=ROOT, check=False)
    m = re.search(r"dry run \(train only\): seed 0 train RMSE ([0-9.]+)", txt)
    if rc != 0 or not m:
        status("gate", ok=False, rc=rc)
        raise Abort("gate run failed (rc=%s); test record untouched" % rc)
    v = float(m.group(1))
    ok = abs(v - GATE_TRAIN_RMSE) <= GATE_TOL
    status("gate", ok=ok, train_rmse_seed0=v, expected=GATE_TRAIN_RMSE, tol=GATE_TOL)
    log("GATE train RMSE seed 0 =", v, "expected", GATE_TRAIN_RMSE, "+-", GATE_TOL, "->", "PASS" if ok else "FAIL")
    if not ok:
        raise Abort("gate: train RMSE %.4f differs from the local dry run %.4f by more than %.3f; test record untouched" % (v, GATE_TRAIN_RMSE, GATE_TOL))


def stage_final():
    status("final", started=True)
    cmd = [PY, "ct/final.py", FREEZE, "--seeds", *SEEDS]
    rc, txt = sh(cmd, "final", cwd=ROOT, check=False, on_line=lambda l: snapshot() if l.startswith("seed ") else None)
    snapshot()
    status("final", ok=(rc == 0), rc=rc)
    if rc != 0:
        raise Abort("final.py exited with %s (scored seeds are in TEST-LOG.md); it is NOT re-run" % rc)


def optional(stage, cmd, name):
    try:
        rc, _ = sh(cmd, name, cwd=ROOT, check=False)
        status(stage, ok=(rc == 0), rc=rc)
    except Exception:
        status(stage, ok=False, error=traceback.format_exc()[-600:])
        log(stage, "FAILED:", traceback.format_exc())
    snapshot()


def main():
    stage_banner()
    stage_payload()
    stage_venv()
    stage_git()
    stage_data()
    stage_gate()
    stage_final()
    optional("compare_ref", [PY, "ct/compare_ref.py", NAME], "compare_ref")
    optional("plots", [PY, "ct/plots.py", NAME], "plots")
    optional("aggregate", [PY, "tools/ct_aggregate.py", NAME], "aggregate")
    optional("edge", [PY, "tools/ct_edge_run.py", FREEZE, "--seed", "0", "--out", "edge_out"], "edge")
    log("ALL STAGES DONE")


if __name__ == "__main__":
    try:
        main()
    except Abort as e:
        log("ABORT:", e)
        status("abort", msg=str(e))
        snapshot()
        sys.exit(2)
    except Exception:
        log("CRASH:", traceback.format_exc())
        status("crash", tb=traceback.format_exc()[-800:])
        snapshot()
        sys.exit(3)
    snapshot()
    shutil.rmtree(ROOT + "/data", ignore_errors=True)
    log("elapsed", round(time.time() - T0), "s")
